package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class TimelineOverrideApiTest extends FinalValidationApiTest {
 @org.springframework.beans.factory.annotation.Autowired com.rpsbattle.tournament.timeline.TimelineAccessGuard access;
 @Test void previousEmergencyQuotaIsRetainedWhenGlobalCodingWindowIsExtended()throws Exception{String base=exam("ALLOW_EMERGENCY_RESUBMISSION");ready(base,130);freeze(base);hiddenFailure();enqueue(base);var failed=finalDone(base).path("finalValidation");var t=tournament(base);managerRequest(base+"/final-validations/"+failed.path("id").asText()+"/emergency","POST",Map.of("revision",t.revision,"reason","First emergency window","deadline",START.plusSeconds(250)),200);assertThat(access.versionLimit(t,account.id().value())).isEqualTo(t.botPolicy.maxSubmissionVersions()+3);managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_CODING","value",START.plusSeconds(300),"reason","Extend for everyone"),200);assertThat(access.versionLimit(t,account.id().value())).isEqualTo(t.botPolicy.maxSubmissionVersions()+6);}
 @Test void policyCanForbidReopeningAfterFreeze()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);var t=tournament(base);var value=(com.fasterxml.jackson.databind.node.ObjectNode)json.valueToTree(t.botPolicy);value.put("allowResubmitBeforeDeadline",false);var policy=json.treeToValue(value,TournamentBotPolicy.class);ownedTournaments.submissionMutation(t,com.rpsbattle.auth.AuthService.sessionAuthentication(account),()->{t.botPolicy=policy;tournaments.changed(t);});managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_CODING","value",START.plusSeconds(250),"reason","Policy forbids reopening"),409);assertThat(t.timeline.codingCloseAt()).isEqualTo(START.plusSeconds(180));}
 @Test void extendedCheckInRestoresValidMissedParticipantBeforeStart()throws Exception{String base=exam("DISQUALIFY");ready(base,130);freeze(base);enqueue(base);finalDone(base);var t=tournament(base);when(clock.instant()).thenReturn(START.plusSeconds(660));ownedTournaments.expireTimelineCheckIns();assertThat(t.participants).isEmpty();managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_CHECK_IN","value",START.plusSeconds(700),"reason","Restore check-in after network interruption"),200);assertThat(t.participants).hasSize(1);request(base+"/check-in","POST",Map.of(),200);assertThat(t.registrations.getFirst().status()).isEqualTo(TournamentRegistration.Status.CHECKED_IN);assertThat(request(base+"/participant-flow","GET",null,200).path("participantStatus").asText()).isEqualTo("CHECKED_IN");}
 @Test void frozenDeadlineExtensionPreservesHistoryFencesOldJobAndRevalidatesNewVersion()throws Exception{
  String base=exam("DISQUALIFY");ready(base,130);var original=freeze(base).path("frozenSubmission");enqueue(base);var stale=queue.lease();assertThat(stale.finalValidationId()).isNotNull();var t=tournament(base);managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_CODING","value",START.plusSeconds(250),"reason","Reviewed outage; reopen coding"),200);var flow=request(base+"/participant-flow","GET",null,200);assertThat(flow.path("phase").asText()).isEqualTo("CODING_OPEN");assertThat(flow.path("participantStatus").asText()).isEqualTo("CODING");assertThat(flow.path("emergencyCoding").asBoolean()).isFalse();assertThat(submissions.frozenMine(t.id,account.id().value(),START.plusSeconds(180)).versionId().toString()).isEqualTo(original.path("versionId").asText());finalWorker.run(stale);assertThat(request(base+"/participant-flow","GET",null,200).path("finalValidation").isNull()).isTrue();
  managerRequest(base+"/final-validations/"+stale.finalValidationId()+"/retry","POST",Map.of("revision",t.revision,"reason","Old final must stay superseded"),409);
  when(clock.instant()).thenReturn(START.plusSeconds(220));var replacement=ready(base,220);when(clock.instant()).thenReturn(START.plusSeconds(250));deadlines.processDeadlines();when(clock.instant()).thenReturn(START.plusSeconds(260));finalService.process(t.id);flow=finalDone(base);assertThat(flow.path("submissionStatus").asText()).isEqualTo("BOT_READY");assertThat(flow.path("finalValidation").path("versionId").asText()).isEqualTo(replacement.path("version").path("id").asText());assertThat(jdbc.queryForObject("select count(*) from tournament_coding_freezes where tournament_id=?",Integer.class,UUID.fromString(t.id))).isEqualTo(2);var audit=t.operations.audit().stream().filter(a->a.type().equals("TIMELINE_OVERRIDE_EXTEND_CODING")).findFirst().orElseThrow();assertThat(audit.actor()).isEqualTo(organizer(base).user().id().value());assertThat(audit.reason()).contains("Reviewed outage");assertThat(audit.beforeValue()).contains(START.plusSeconds(180).toString());assertThat(audit.afterValue()).contains(START.plusSeconds(250).toString());assertThat(audit.at()).isNotNull();
 }
 @Test void overridesRequireOwnerFreshRevisionReasonAndValidChronology()throws Exception{
  String base=cup("BOTH",true);var t=tournament(base);long revision=t.revision;managerRequest(base+"/timeline/override","POST",Map.of("revision",revision,"action","EXTEND_REGISTRATION","value",START.plusSeconds(90),"reason","Extend registration"),200);assertThat(t.timeline.codingOpenAt()).isEqualTo(START.plusSeconds(150));managerRequest(base+"/timeline/override","POST",Map.of("revision",revision,"action","EXTEND_REGISTRATION","value",START.plusSeconds(100),"reason","Stale"),409);managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_REGISTRATION","value",START.plusSeconds(100),"reason",""),400);managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_REGISTRATION","value",START.plusSeconds(20),"reason","Invalid"),400);request("/api/auth/logout","POST",Map.of(),200);account=null;loginAccount();request(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_REGISTRATION","value",START.plusSeconds(100),"reason","Not owner"),403);
 }
 @Test void earlyCodingCheckInExtensionAndStartDelayUseAuditedTimeline()throws Exception{
  String base=cup("BOTH",true);var t=tournament(base);managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","START_CODING_EARLY","value",START.plusSeconds(30),"reason","All entries reviewed"),200);assertThat(request(base+"/participant-flow","GET",null,200).path("canModifyWorkspace").asBoolean()).isTrue();managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_CHECK_IN","value",START.plusSeconds(300),"reason","More check-in time"),200);managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","DELAY_START","value",START.plusSeconds(400),"reason","Delay start"),200);assertThat(t.timeline.tournamentStartAt()).isEqualTo(START.plusSeconds(400));assertThat(t.operations.audit().stream().filter(a->a.type().startsWith("TIMELINE_OVERRIDE_"))).hasSize(3);
 }

 @Test void registrationExtensionReopensAdmissionAndClosesAgainAtTheNewDeadline()throws Exception{
  String base=cup("BOTH",true);var t=tournament(base);when(clock.instant()).thenReturn(START.plusSeconds(70));
  assertThat(managerRequest(base+"/registration-summary","GET",null,200).path("registrationOpen").asBoolean()).isFalse();
  managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_REGISTRATION","value",START.plusSeconds(100),"reason","Extend admission after scheduled close"),200);
  var summary=managerRequest(base+"/registration-summary","GET",null,200);assertThat(summary.path("registrationOpen").asBoolean()).isTrue();assertThat(summary.path("control").path("closedAt").isNull()).isTrue();
  request("/api/auth/logout","POST",Map.of(),200);account=null;loginAccount();
  assertThat(request(base+"/participant-registration","POST",Map.of("rulesAccepted",true,"intendedLanguage","PYTHON"),200).path("registrationStatus").asText()).isEqualTo("NEEDS_REVIEW");
  when(clock.instant()).thenReturn(START.plusSeconds(100));assertThat(request(base+"/participant-registration","POST",Map.of("rulesAccepted",true,"intendedLanguage","PYTHON"),409).path("error").asText()).isEqualTo("REGISTRATION_NOT_OPEN");
  assertThat(managerRequest(base+"/registration-summary","GET",null,200).path("control").path("closedAt").asText()).isEqualTo(START.plusSeconds(100).toString());
 }
 @Test void registrationExtensionCannotUnlockAnExplicitlyFinalizedRoster()throws Exception{
  String base=cup("BOTH",true);var t=tournament(base);request("/api/auth/logout","POST",Map.of(),200);account=null;loginAccount();
  var app=request(base+"/participant-registration","POST",Map.of("rulesAccepted",true,"intendedLanguage","PYTHON"),200);
  managerRequest(base+"/participant-applications/"+app.path("registration").path("id").asText()+"/review","POST",Map.of("revision",t.revision,"decision","APPROVED","reason","Second eligible player"),200);
  when(clock.instant()).thenReturn(START.plusSeconds(70));managerRequest(base+"/registration-summary","GET",null,200);
  managerRequest(base+"/roster/lock","POST",Map.of("revision",t.revision,"reason","Finalize roster"),200);var before=t.timeline;long revision=t.revision;
  assertThat(managerRequest(base+"/timeline/override","POST",Map.of("revision",t.revision,"action","EXTEND_REGISTRATION","value",START.plusSeconds(100),"reason","Must not reopen locked roster"),409).path("error").asText()).isEqualTo("ROSTER_LOCKED");
  assertThat(t.timeline).isEqualTo(before);assertThat(t.revision).isEqualTo(revision);assertThat(managerRequest(base+"/registration-summary","GET",null,200).path("control").path("lockedAt").isNull()).isFalse();
 }
}
